/** Short, real teaching text for a lesson, chosen by topic keywords in the title. */
function lesson_body_for(string $paper, string $title): string {
    $t = strtolower($title);
    $bodies = [
        'noun' => "A noun names a person, a place, a thing or an idea. Example: Rahim is a person, Dhaka is a place, book is a thing, and honesty is an idea.\n\nবাংলা: যে শব্দ দিয়ে কোনো ব্যক্তি, স্থান, বস্তু বা ভাবের নাম বোঝায়, তাকে Noun বলে।\n\nPractice: Underline the nouns in this sentence — \"Rahim reads a book in Dhaka every morning.\" (Answer: Rahim, book, Dhaka, morning.)",
        'pronoun' => "A pronoun takes the place of a noun so we do not repeat the same name again and again. Example: \"Rahim is my friend. He is a good student.\" Here \"he\" is a pronoun for Rahim.\n\nবাংলা: Noun-এর বদলে যে শব্দ বসে, তাকে Pronoun বলে। যেমন: I, you, he, she, it, we, they.\n\nPractice: Replace the noun with a pronoun — \"Rina loves Rina's mother.\" (Answer: Rina loves her mother.)",
        'adjective' => "An adjective describes a noun. It tells us what kind, how many, or which one. Example: a red pen, three books, that boy.\n\nবাংলা: যে শব্দ Noun-এর দোষ, গুণ, সংখ্যা বা অবস্থা বোঝায়, তাকে Adjective বলে।\n\nPractice: Add an adjective — \"The ___ river is wide.\" (Possible answer: The big river is wide.)",
        'degrees of comparison' => "Adjectives have three degrees: positive, comparative and superlative. Example: big — bigger — biggest; good — better — best.\n\nবাংলা: তুলনা বোঝাতে Adjective-এর রূপ বদলায়। দুজনের মধ্যে তুলনায় comparative, সবার মধ্যে তুলনায় superlative।\n\nPractice: Fill in — \"Rahim is ___ than Karim.\" (taller) \"Dhaka is the ___ city in Bangladesh.\" (biggest)",
        'adverb' => "An adverb describes a verb, an adjective or another adverb. It often answers how, when or where. Example: She speaks slowly. He came yesterday.\n\nবাংলা: যে শব্দ Verb, Adjective বা অন্য Adverb-কে বর্ণনা করে, তাকে Adverb বলে। অনেক Adverb-এর শেষে -ly থাকে: slowly, carefully.\n\nPractice: Add an adverb — \"The boy walks ___.\" (slowly)",
        'verb' => "A verb is a doing word or a being word. It tells what someone does or is. Example: read, write, play, am, is, are.\n\nবাংলা: যে শব্দ দিয়ে কোনো কাজ করা বা হওয়া বোঝায়, তাকে Verb বলে।\n\nPractice: Find the verb — \"The children play football in the field.\" (Answer: play)",
        'preposition' => "A preposition shows the relation between a noun and another word — usually place or time. Example: The book is on the table. I was born in 2010.\n\nবাংলা: Preposition Noun বা Pronoun-এর সঙ্গে অন্য শব্দের সম্পর্ক দেখায়। যেমন: in, on, at, under, between, after.\n\nPractice: Fill in — \"The cat is ___ the table.\" (under)",
        'conjunction' => "A conjunction joins words, phrases or sentences. Common conjunctions are and, but, or, because, so, although.\n\nবাংলা: যে শব্দ দুটি শব্দ, বাক্যাংশ বা বাক্যকে যুক্ত করে, তাকে Conjunction বলে।\n\nPractice: Join with \"but\" — \"He is rich. He is not happy.\" (Answer: He is rich but he is not happy.)",
        'interjection' => "An interjection expresses a sudden feeling: joy, sorrow, surprise or pain. Example: Hurrah! Alas! Oh! Wow!\n\nবাংলা: হঠাৎ মনের ভাব (আনন্দ, দুঃখ, বিস্ময়) প্রকাশ করে যে শব্দ, তাকে Interjection বলে। এর পরে সাধারণত বিস্ময় চিহ্ন (!) বসে।\n\nPractice: Which interjection shows joy? (Answer: Hurrah!)",
        'article' => "A, an and the are articles. Use \"a\" before a consonant sound (a book), \"an\" before a vowel sound (an apple), and \"the\" for something specific (the sun, the book on the table).\n\nবাংলা: A, An, The-কে Article বলে। A/An অনির্দিষ্ট কিছু বোঝায়, The নির্দিষ্ট কিছু বোঝায়।\n\nPractice: Fill in — \"___ honest man is respected.\" (Answer: An)",
        'tense' => "Tense tells the time of an action: present, past or future. Example: I read (present), I read yesterday (past), I will read tomorrow (future).\n\nবাংলা: কাজ কখন হয় — এখন, আগে, নাকি পরে — তাই Tense দিয়ে বোঝায়।\n\nPractice: Change to past tense — \"She goes to school.\" (Answer: She went to school.)",
        'modal' => "Modals are helping verbs that show ability, permission, possibility or duty: can, could, may, might, must, should, will, would.\n\nবাংলা: Can = পারা, May = অনুমতি, Must = অবশ্যই, Should = উচিত।\n\nPractice: Fill in — \"You ___ obey your parents.\" (Answer: should / must)",
        'conditional' => "A conditional sentence has two parts: if + condition, and the result. First conditional (real): If it rains, we will stay at home. Second conditional (imaginary): If I were rich, I would help the poor.\n\nবাংলা: If দিয়ে শর্ত বোঝায়। প্রথম শর্ত বাস্তব, দ্বিতীয় শর্ত কল্পনা।\n\nPractice: Complete — \"If you study hard, you ___.\" (will succeed)",
        'passive' => "In the passive voice, the object of the active sentence becomes the subject. Active: Rahim writes a letter. Passive: A letter is written by Rahim.\n\nবাংলা: Passive voice-এ কাজটি কার দ্বারা হলো, সেটাই গুরুত্বপূর্ণ। be + verb-এর past participle দিয়ে গঠিত হয়।\n\nPractice: Change to passive — \"The teacher praised the boy.\" (Answer: The boy was praised by the teacher.)",
        'narration' => "Narration means reporting what someone said. Direct: He said, \"I am happy.\" Indirect: He said that he was happy.\n\nবাংলা: Direct speech-এ বক্তার কথা হুবহু থাকে; Indirect speech-এ tense ও pronoun বদলে যায়।\n\nPractice: Change to indirect — She said, \"I will come tomorrow.\" (Answer: She said that she would come the next day.)",
        'punctuation' => "Punctuation marks make writing clear: full stop (.), comma (,), question mark (?), exclamation mark (!), capital letters at the start of a sentence and for proper nouns.\n\nবাংলা: বিরাম চিহ্ন ছাড়া লেখা বোঝা কঠিন। বাক্যের শেষে full stop, প্রশ্নে question mark বসে।\n\nPractice: Punctuate — \"what is your name\" (Answer: What is your name?)",
        'capital' => "Use a capital letter at the beginning of a sentence, for names of people and places, for days and months, and for the word \"I\".\n\nবাংলা: বাক্যের শুরুতে, ব্যক্তি ও স্থানের নামে, দিন ও মাসের নামে বড় হাতের অক্ষর বসে।\n\nPractice: Correct — \"rahim lives in dhaka.\" (Answer: Rahim lives in Dhaka.)",
        'letter' => "A letter has five parts: the address, the date, the greeting (Dear Sir / Dear Rahim), the body, and the closing (Yours faithfully / Your loving friend) with your name.\n\nবাংলা: চিঠিতে ঠিকানা, তারিখ, সম্বোধন, মূল বক্তব্য ও শেষাংশ থাকে।\n\nPractice: Write three lines of a letter to your friend inviting him to your birthday.",
        'e-mail' => "An e-mail needs a clear subject line, a polite greeting, short clear sentences, and a proper closing with your name. Keep it short and to the point.\n\nবাংলা: ই-মেইলে বিষয় (subject) স্পষ্ট লিখতে হয়, বাক্য ছোট ও ভদ্র হতে হয়।\n\nPractice: Write an e-mail to your teacher asking for two days' leave.",
        'cv' => "A CV (curriculum vitae) lists your name, address, phone, education, skills and experience in short, clear points. Use simple words and check the spelling twice.\n\nবাংলা: CV-তে নিজের পরিচয়, শিক্ষা ও দক্ষতা সংক্ষেপে সাজিয়ে লিখতে হয়।\n\nPractice: Write the first five lines of your own CV.",
        'paragraph' => "A good paragraph has one main idea, a topic sentence at the start, and supporting sentences that explain it. Keep it 100–150 words for exams.\n\nবাংলা: অনুচ্ছেদে একটাই মূল ভাব থাকে। প্রথম বাক্যে মূল কথা, পরের বাক্যগুলোতে ব্যাখ্যা।\n\nPractice: Write a paragraph of five sentences on \"My School\".",
        'story' => "A completing story needs a clear beginning, a middle with a problem, and an ending with a lesson. Read the given part carefully and keep the same tense and characters.\n\nবাংলা: গল্প শেষ করার সময় শুরু, মাঝখানের সমস্যা ও শেষে শিক্ষা — এই তিনটি অংশ রাখতে হয়।\n\nPractice: Complete this story in five sentences: \"Once there was a poor farmer...\"",
        'graph' => "To describe a graph or chart, first say what it shows, then give the highest and lowest figures, then compare two or three points, and finish with a short conclusion.\n\nবাংলা: গ্রাফ বর্ণনায় প্রথমে কী দেখাচ্ছে বলো, তারপর সবচেয়ে বেশি ও কম সংখ্যা দাও, তুলনা করো, শেষে সংক্ষিপ্ত মন্তব্য লেখো।\n\nPractice: Look at any chart in your book and write four sentences about it.",
        'dialogue' => "A dialogue is a conversation between two people. Use natural, short sentences, greet each other first, and end politely. Keep the same topic from start to finish.\n\nবাংলা: সংলাপে দুজনের কথা স্বাভাবিক ও ছোট বাক্যে হয়। শুরুতে সালাম/শুভেচ্ছা, শেষে বিদায়।\n\nPractice: Write a dialogue of six lines between two friends about their exam preparation.",
        'greeting' => "Say \"Hello\" or \"Good morning\" when you meet someone. Ask \"How are you?\" and answer \"I am fine, thank you. And you?\" Small talk makes English friendly.\n\nবাংলা: দেখা হলে Good morning বলো, How are you? জিজ্ঞেস করো। এভাবেই কথোপকথন শুরু হয়।\n\nPractice: Greet your teacher in English tomorrow morning.",
        'introduc' => "To introduce yourself, say your name, where you live, your class, and one thing you like. Example: \"My name is Rahim. I live in Dhaka. I read in Class 6. I like reading books.\"\n\nবাংলা: নিজের পরিচয়ে নাম, ঠিকানা, ক্লাস ও একটি পছন্দের কথা বলো।\n\nPractice: Introduce yourself in four English sentences.",
        'phone' => "On the phone, start with \"Hello, this is Rahim speaking.\" Speak slowly and clearly. If you cannot hear, say \"Could you please repeat that?\"\n\nবাংলা: ফোনে কথা বলার সময় ধীরে ও স্পষ্ট করে বলো। না শুনলে ভদ্রভাবে আবার বলতে বলো।\n\nPractice: Practise a phone call with a friend: ask for your teacher.",
        'direction' => "To give directions, use words like go straight, turn left, turn right, next to, opposite, and near. Example: \"Go straight, then turn left. The school is next to the mosque.\"\n\nবাংলা: দিক নির্দেশে go straight, turn left/right, next to, opposite শব্দগুলো ব্যবহার করো।\n\nPractice: Give directions from your home to your school in English.",
        'doctor' => "At the doctor, describe your problem clearly: \"I have a fever.\" \"My head aches.\" \"I have had a cough for two days.\" Answer the doctor's questions in short sentences.\n\nবাংলা: ডাক্তারের কাছে সমস্যাটা স্পষ্ট করে বলো — কোথায় ব্যথা, কতদিন ধরে।\n\nPractice: Act out a visit to the doctor with a friend.",
        'market' => "At the market, ask the price: \"How much is this?\" Bargain politely: \"Can you give it for 50 taka?\" Say \"Thank you\" after buying.\n\nবাংলা: বাজারে দাম জিজ্ঞেস করো — How much is this? ভদ্রভাবে দরদাম করো।\n\nPractice: Practise buying vegetables in English with a friend.",
        'weather' => "To talk about the weather, say \"It is sunny today.\" \"It is raining.\" \"It is very hot.\" Ask: \"What is the weather like today?\"\n\nবাংলা: আবহাওয়া নিয়ে কথা বলতে It is sunny / It is raining বলো।\n\nPractice: Describe today's weather in three English sentences.",
        'describ' => "To describe a person or place, use adjectives: tall, short, kind, beautiful, big, quiet. Start with the general idea, then add details. Example: \"My mother is kind and hard-working.\"\n\nবাংলা: বর্ণনায় Adjective ব্যবহার করো — লম্বা, সুন্দর, দয়ালু। প্রথমে সাধারণ কথা, তারপর বিবরণ।\n\nPractice: Describe your best friend in five English sentences.",
        'past' => "To talk about the past, use the past tense: \"Yesterday I visited my grandmother.\" \"We played football last Friday.\" Words like yesterday, last week and ago show past time.\n\nবাংলা: অতীতের কথা বলতে past tense ব্যবহার করো। Yesterday, last week, ago শব্দগুলো অতীত বোঝায়।\n\nPractice: Tell your friend what you did yesterday in four sentences.",
        'plan' => "To talk about plans, use \"going to\" or \"will\": \"I am going to visit Cox's Bazar.\" \"I will study hard this year.\" Ask: \"What are you going to do tomorrow?\"\n\nবাংলা: ভবিষ্যৎ পরিকল্পনায় going to বা will ব্যবহার করো।\n\nPractice: Tell your friend your plan for the next holiday.",
        'opinion' => "To give your opinion, say \"I think...\", \"In my opinion...\" or \"I believe...\". Give one reason after it. Example: \"I think reading is the best habit because it increases knowledge.\"\n\nবাংলা: মতামত দিতে I think বা In my opinion বলো, তারপর একটি কারণ দাও।\n\nPractice: Give your opinion: \"Is mobile phone good for students?\"",
        'discussion' => "In a group discussion, listen to others, speak one at a time, and say \"I agree\" or \"I disagree because...\". Keep your points short and clear.\n\nবাংলা: দলীয় আলোচনায় অন্যের কথা শোনো, একে একে বলো, I agree বা I disagree because... বলো।\n\nPractice: Discuss with friends: \"Should students use social media?\"",
        'presentation' => "A good presentation has three parts: a greeting and topic, the main points (two or three), and a closing thank-you. Speak slowly, look at your listeners, and do not read every word.\n\nবাংলা: উপস্থাপনায় শুরুতে বিষয় বলো, মাঝে দুই-তিনটি মূল কথা, শেষে ধন্যবাদ। ধীরে বলো, শ্রোতাদের দিকে তাকাও।\n\nPractice: Prepare a two-minute presentation on \"My Favourite Book\".",
        'interview' => "In an interview, greet politely, answer in full sentences, and give examples. Common questions: \"Tell me about yourself.\" \"Why do you want this job?\" \"What are your strengths?\"\n\nবাংলা: সাক্ষাৎকারে ভদ্রভাবে সালাম দাও, পূর্ণ বাক্যে উত্তর দাও, উদাহরণ দাও।\n\nPractice: Answer in English: \"Tell me about yourself.\"",
        'pronunciation' => "English has 20 vowel sounds and 24 consonant sounds. Practise the difference between similar sounds: ship/sheep, full/fool, cat/cut. Listen and repeat every day.\n\nবাংলা: ইংরেজিতে স্বরধ্বনি ও ব্যঞ্জনধ্বনির পার্থক্য শেখা জরুরি। প্রতিদিন শুনে শুনে অনুশীলন করো।\n\nPractice: Say aloud: ship, sheep, full, fool — and notice the difference.",
        'stress' => "In English, some syllables are stressed (said louder and longer). Example: PHO-to-graph, pho-TO-gra-phy. Wrong stress can change the meaning, so listen carefully.\n\nবাংলা: ইংরেজি শব্দের কিছু অংশ জোরে বলতে হয়। ভুল জোরে বললে অর্থ বদলে যেতে পারে।\n\nPractice: Say these words with the stressed part louder: teacher, important, today.",
        'mistake' => "Common spoken mistakes: saying \"I am agree\" (say \"I agree\"), \"more better\" (say \"better\"), \"discuss about\" (say \"discuss\"). At Redway we mark every mistake in red — and then we fix it. ভুল করো, বোঝো, সঠিক করো।\n\nবাংলা: ভুল ধরা পড়লেই শেখা হয়। নিজের ভুলের খাতায় লিখে রাখো, সপ্তাহে আবার চেষ্টা করো।\n\nPractice: Correct these sentences: \"He is more taller than me.\" \"I am agree with you.\"",
        'review' => "Review is the most important part of learning. Look at your Mistake Notebook (ভুলের খাতা), read the red marks again, and try the same questions once more. A mistake you fix is a mark turned green.\n\nবাংলা: পুরোনো ভুলগুলো আবার দেখো, একই প্রশ্ন আবার চেষ্টা করো। ঠিক করা ভুলই আসল শেখা।\n\nPractice: Open your Mistake Notebook and retry three questions you got wrong last week.",
        'reading' => "Read the passage slowly and find the main idea first. Then read the questions and look for the answers in the passage. Do not guess — find the line that proves your answer.\n\nবাংলা: অনুচ্ছেদ পড়ে প্রথমে মূল ভাব বোঝো, তারপর প্রশ্ন পড়ে উত্তর খোঁজো।\n\nPractice: Read any passage in your book and write its main idea in one sentence.",
        'vocabulary' => "Learn new words in groups: word, meaning, and one sentence. Example: honest — সৎ — \"He is an honest man.\" Write new words in your notebook and use them the same day.\n\nবাংলা: নতুন শব্দ শিখতে শব্দ, অর্থ ও একটি বাক্য — তিনটিই একসাথে লেখো।\n\nPractice: Learn five new words from today's lesson and make a sentence with each.",
        'sentence' => "A sentence has a subject and a verb, and it makes complete sense. Example: Birds fly. (Subject: Birds, Verb: fly.) A sentence starts with a capital letter and ends with a full stop, question mark or exclamation mark.\n\nবাংলা: বাক্যে Subject ও Verb থাকে এবং সম্পূর্ণ অর্থ হয়। বড় হাতের অক্ষর দিয়ে শুরু, যতিচিহ্ন দিয়ে শেষ।\n\nPractice: Make three sentences about your school.",
        'agreement' => "The verb must agree with its subject: singular subject takes a singular verb. Example: He plays. They play. \"The boys are playing.\"\n\nবাংলা: Subject একবচন হলে Verb একবচন, বহুবচন হলে Verb বহুবচন।\n\nPractice: Fill in — \"The students ___ reading.\" (are)",
        'question' => "Wh-questions ask for information: What, Where, When, Who, Why, How. Example: \"Where do you live?\" \"Why are you late?\" Remember: the helping verb comes before the subject.\n\nবাংলা: What, Where, When, Who, Why, How দিয়ে তথ্য জানতে চাওয়া হয়।\n\nPractice: Make a Wh-question for this answer: \"I live in Dhaka.\" (Where do you live?)",
        'summary' => "A summary is the short form of a passage. Read it twice, find the main points, and write them in your own words in about one-third of the length. Do not copy whole sentences.\n\nবাংলা: সারাংশে মূল কথাগুলো নিজের ভাষায় সংক্ষেপে লিখতে হয়। পুরো বাক্য হুবহু নকল করা যাবে না।\n\nPractice: Write a summary of any short passage in five lines.",
        'essay' => "An essay has three parts: introduction, body and conclusion. Start with the topic, explain it with two or three points and examples, and end with your own opinion.\n\nবাংলা: রচনায় ভূমিকা, মূল অংশ ও উপসংহার থাকে। মাঝে দুই-তিনটি যুক্তি ও উদাহরণ দাও।\n\nPractice: Write an essay of 150 words on \"The Importance of Education\".",
        'flow chart' => "A flow chart shows steps in order, one after another, using short phrases and arrows. Keep each step to a few words and follow the order in the passage.\n\nবাংলা: ফ্লো চার্টে ধাপগুলো ক্রমানুসারে ছোট বাক্যাংশে লেখা হয়।\n\nPractice: Make a flow chart of how a student prepares for an exam.",
        'cloze' => "In a cloze test, read the whole passage first to understand the meaning, then fill each gap with a word that fits the grammar and the sense. Check your answer by reading the sentence again.\n\nবাংলা: শূন্যস্থান পূরণের আগে পুরো অনুচ্ছেদ পড়ে অর্থ বোঝো, তারপর ব্যাকরণ ও অর্থ মিলিয়ে শব্দ বসাও।\n\nPractice: Fill the gaps in any cloze passage in your book.",
        'transformation' => "Transformation means changing a sentence from one form to another without changing its meaning. Example: Affirmative: He is a good boy. Negative: He is not a bad boy.\n\nবাংলা: অর্থ না বদলে বাক্যের রূপ বদলানোই Transformation।\n\nPractice: Change to negative: \"He is an honest man.\"",
        'modifier' => "A modifier is a word or phrase that adds information to another word. Example: \"a red pen\" (red modifies pen), \"a very good student\" (very modifies good).\n\nবাংলা: Modifier অন্য শব্দের অর্থকে স্পষ্ট করে — যেমন red pen-এ red শব্দটি pen-কে বর্ণনা করে।\n\nPractice: Add a modifier: \"The ___ boy won the prize.\"",
        'synonym' => "Synonyms are words with the same or similar meaning: happy — glad, big — large. Antonyms are words with opposite meanings: hot — cold, rich — poor.\n\nবাংলা: সমার্থক শব্দের অর্থ একই, বিপরীতার্থক শব্দের অর্থ উল্টো।\n\nPractice: Give the synonym of \"brave\" and the antonym of \"early\".",
        'tag' => "A tag question is a short question added to a statement: \"You are coming, aren't you?\" If the statement is positive, the tag is negative, and the other way round.\n\nবাংলা: বাক্যের শেষে ছোট প্রশ্ন জুড়ে দেওয়াই Tag Question। বাক্য হ্যাঁ-বোধক হলে tag না-বোধক হয়।\n\nPractice: Add a tag — \"He is a good student, ___?\" (isn't he)",
        'completing' => "To complete a sentence, read the first part and think what fits: a verb, a clause, or a phrase. The completed sentence must make full sense and match the tense.\n\nবাংলা: অসম্পূর্ণ বাক্য শেষ করতে প্রথম অংশ পড়ে ভাবো কী বসবে — Verb, Clause নাকি Phrase।\n\nPractice: Complete — \"If I had enough money, I ___.\"",
        'connector' => "Sentence connectors join ideas: however, therefore, moreover, firstly, finally, on the other hand. They make writing smooth and clear.\n\nবাংলা: Connector দিয়ে বাক্যের ভাব জোড়া লাগে। যেমন: however (তবে), therefore (সুতরাং), moreover (অধিকন্তু)।\n\nPractice: Join with \"therefore\": \"He studied hard. He passed the exam.\"",
        'speech' => "Speech means direct and indirect narration. Direct: He said, \"I am happy.\" Indirect: He said that he was happy. In indirect speech, the tense and pronouns change.\n\nবাংলা: Direct speech-এ বক্তার কথা হুবহু থাকে; Indirect speech-এ tense ও pronoun বদলে যায়।\n\nPractice: Change to indirect — She said, \"I will come tomorrow.\"",
        'voice' => "In the passive voice, the object of the active sentence becomes the subject. Active: Rahim writes a letter. Passive: A letter is written by Rahim.\n\nবাংলা: Passive voice-এ কাজটি কার দ্বারা হলো, সেটাই গুরুত্বপূর্ণ। be + verb-এর past participle দিয়ে গঠিত হয়।\n\nPractice: Change to passive — \"The teacher praised the boy.\"",
    ];
    foreach ($bodies as $keyword => $body) {
        if (str_contains($t, $keyword)) return $body;
    }
    if ($paper === 'Spoken English') {
        return "In this lesson we practise speaking about \"{$title}\". Listen to the example, then say it yourself — speaking is learned by speaking, not by reading.\n\nExample: \"Hello! Today I want to talk about {$title}.\" Now try: make three English sentences about this topic and say them aloud.\n\nবাংলা: এই পাঠে \"{$title}\" নিয়ে ইংরেজিতে কথা বলার অনুশীলন করো। জোরে জোরে বলো — ভুল হলে লাল কলমে ধরে ঠিক করব।\n\nPractice: Record yourself (or tell a friend) three sentences about this topic.";
    }
    if ($paper === '2nd Paper') {
        return "In this lesson we learn about \"{$title}\". Read the rule carefully, look at the examples, and then try the practice question yourself. Remember the Red Pen Method: find the mistake, understand it, and correct it.\n\nবাংলা: এই পাঠে \"{$title}\" শিখব। নিয়মটি পড়ো, উদাহরণ দেখো, তারপর নিজে চেষ্টা করো। ভুল করো, বোঝো, সঠিক করো।\n\nPractice: Write three English sentences using what you learned in this lesson.";
    }
    return "In this lesson we read and learn about \"{$title}\". Read the text slowly, find the main idea, and learn the new words. Then answer the questions in your own words.\n\nবাংলা: এই পাঠে \"{$title}\" পড়ব ও শিখব। ধীরে পড়ো, মূল ভাব বোঝো, নতুন শব্দগুলো খাতায় লেখো।\n\nPractice: Write the main idea of this lesson in two English sentences.";
}

/** Insert all lessons for every course, only when the lessons table is empty. */
function seed_lessons(PDO $pdo): void {
    $count = (int)$pdo->query('SELECT COUNT(*) FROM lessons')->fetchColumn();
    if ($count > 0) return;
    $st = $pdo->prepare('INSERT INTO lessons (course_id, lesson_no, title, body, created_at) VALUES (?,?,?,?,?)');
    $now = date('Y-m-d H:i');
    foreach ($pdo->query('SELECT * FROM courses ORDER BY id')->fetchAll() as $course) {
        $titles = lesson_titles_for_course($course['paper'], $course['class_level']);
        $n = (int)$course['lessons'];
        for ($i = 1; $i <= $n; $i++) {
            $title = $titles[$i - 1] ?? ('Lesson ' . $i . ' — ' . $course['paper']);
            $st->execute([(int)$course['id'], $i, $title, lesson_body_for($course['paper'], $title), $now]);
        }
    }
}
